/* notes */
WITH dups AS (
    SELECT *,
        ROW_NUMBER() OVER (PARTITION BY match_id, player_gamertag, region_code ORDER BY accepted_at) AS rn
    FROM match_responses
)
DELETE FROM match_responses
WHERE response_id IN (
        SELECT response_id
        FROM dups
        WHERE rn > 1);

SELECT * FROM match_responses ORDER BY response_id;
